fn reject_disagreeing_expected_identity(
    validated: &Identity,
    expected: Option<VerifiedIdentity>,
) -> Result<(), Error> {
    if expected.is_some_and(|expected| !expected.agrees_with(validated)) {
        return Err(Error::Conflict(VERIFIED_REGISTRATION_CONFLICT.into()));
    }
    Ok(())
}

